import { test, expect } from '@playwright/test';

test.describe('Notification Message Tests', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/notification_message_rendered');
  });

  test('should display a successful notification when clicking the link', async ({ page }) => {
    await page.getByText('Click here').click();
    const flash = page.getByRole('alert');
    await expect(flash).toBeVisible();
    await expect(flash).toHaveText(/Action successful/);
  });

  test('should display an unsuccessful notification when clicking the link', async ({ page }) => {
    await page.getByText('Click here').click();
    const flash = page.getByRole('alert');
    await expect(flash).toBeVisible();
    await expect(flash).toHaveText(/Action unsuccessful/);

    await page.getByRole('button', { name: 'close' }).click();
    await expect(flash).not.toBeVisible();
  });
});
